// Общие шаги для серии входов (#a55519 #980fd4 #fdc5b2 #808adb). Тексты — со скринов r10 12.11 (веб 390/375, user4).
// Награды выдаёт только админка («כלי בדיקה» → «הענקת תגמול רצף») — тесты НЕ выдают (разрешение было разовым на раунд 10).
// Имя RPC получения награды неизвестно — ловим первую запись в /rest/v1/ после «לקבל את הפרס». Не проверено на живой странице.
import { expect, type Page, type Response } from '@playwright/test';

export const NO_REWARD_HINT =
  'ОКРУЖЕНИЕ: у user4 нет ожидающей награды серии — админка https://magnet-admin.vercel.app → משתמשים → «QA רביעית» → «כלי בדיקה» → «הענקת תגמול רצף» (тест не выдаёт)';

export async function phone(page: Page, width = 390, height = 844) {
  await page.setViewportSize({ width, height });
}

// /settings → «מתנות ורצף» → «רצף כניסות».
export async function openStreak(page: Page) {
  await page.goto('/settings');
  await page.getByText('מתנות ורצף', { exact: true }).first().click();
  await expect(page.getByText('רצף כניסות').first()).toBeVisible({ timeout: 20_000 });
}

// Число в строке «פרסים שצברת» («N בוסטים», «N מתנות חינם» …).
export async function earnedCount(page: Page, word: RegExp): Promise<number> {
  const el = page.getByText(new RegExp(`^\\d+\\s+${word.source}`)).first();
  await el.scrollIntoViewIfNeeded();
  await expect(el).toBeVisible();
  return Number(((await el.textContent()) ?? '').match(/\d+/)?.[0] ?? NaN);
}

// «לבחירת פרס» → лист «בחירת פרס» (падает с подсказкой, если награды нет).
export async function openPicker(page: Page) {
  const btn = page.getByRole('button', { name: 'לבחירת פרס' }).or(page.getByText('לבחירת פרס', { exact: true })).first();
  await expect(btn, NO_REWARD_HINT).toBeVisible({ timeout: 15_000 });
  await btn.click();
  await expect(page.getByText('בחירת פרס', { exact: true }).first()).toBeVisible();
  await expect(page.getByText('כל הכבוד על הרצף!')).toBeVisible();
}

// Выбрать вариант награды в листе (радио/карточка по заголовку).
export async function chooseReward(page: Page, title: 'מתנה' | 'בוסט' | 'סופר לייק' | 'חזרה אחורה') {
  const radio = page.getByRole('radio', { name: new RegExp(title) });
  if (await radio.count()) await radio.first().click();
  else await page.getByText(title, { exact: true }).last().click();
}

export const claimButton = (page: Page) => page.getByRole('button', { name: 'לקבל את הפרס' });
export const isWrite = (r: Response) => r.url().includes('/rest/v1/') && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method());
